func _init():
	var quest_a = load("res://resources/quests/quest_a.tres")
	var quest_b = load("res://resources/quests/quest_b.tres")
	var quest_c = load("res://resources/quests/quest_c.tres")

	print("Loaded quests successfully")

	QuestManager.register_quest(quest_a)
	QuestManager.register_quest(quest_b)
	QuestManager.register_quest(quest_c)

	print("Registered quests")

	if QuestManager.can_start("quest_a"):
		print("Can start A")
	else:
		print("Cannot start A")

	if QuestManager.can_start("quest_b"):
		print("Can start B")
	else:
		print("Cannot start B")

	QuestManager.start_quest("quest_a")
	print("Started A")

	QuestManager.report_progress("Collect Apples", 2)
	print("Progress A: ", quest_a.get_progress())

