	print("Progress A: ", quest_a.get_progress())

	if quest_a.is_complete():
		print("A is complete")
		QuestManager.complete_quest("quest_a")
		print("Completed A")

	if QuestManager.can_start("quest_b"):
		print("Can start B now")

	quit()

